<script setup lang="ts">
import { useRoute } from 'vue-router';
import { useStore } from 'vuex';
import { computed, onMounted, ref } from 'vue';
import { Heading } from '@/shared/ui/text/heading'
import { Text } from '@/shared/ui/text/paragraph';

const route = useRoute()
const store = useStore();
const loading = ref(true);

const blogSlug = computed(() => String(route.params.slug));

const blog = computed(() => {
    return store.getters['blogs/getBlogBySlug'](blogSlug.value);
});

onMounted(async () => {
    if (store.state.blogs.blogData.length === 0) {
        await store.dispatch('blogs/fetchblog');
    }
    loading.value = false;
});

</script>

<template>
    <div v-if="loading">Загрузка...</div>
    <div v-else-if="blog" class="blog-item">
        <Heading tagName="h1" color="dark" size="m">
            {{ blog.title }}
        </Heading>
        <div class="item-content">
            
            <Text tagName="p" size="l" color="dark-gray2" class="blog-text">
                {{ blog.text }}
            </Text>
            <div class="clearfix"></div>
        </div>
    </div>
</template>

<style scoped>
.blog-image {
    float: left;
    width: 300px;
    height: 200px;
    margin-right: 20px;
    margin-bottom: 10px;
    object-fit: cover;
}

.blog-text {
    overflow: hidden;
}

.clearfix {
    clear: both;
}

.item-content {
    margin-top: 20px;
}
</style>